def children_of(pi,pj):
  res=[]
  i=pi+1
  while i<pj:
    if target[i]=='(' and pairs.get(i)==None:
      i+=1; continue
    if target[i]=='(' and pairs[i]<pj and pairs[i]>pi:
      res.append((i,pairs[i]))
      i=pairs[i]+1
    else:
      i+=1
  return res

# The structure is deeply nested. Let me find the two main domains:
# At some level there's a multiloop with 2 branches: left domain and right domain.
# Find the pair (a,b) such that its children list has 2 elements representing the two domains.
